    [InlineData("func stop() -> Never => $abort(\"stop\")\nfunc mk3<s/T, V, X>(y: s/V, z: s/X) -> s/T\n    s is owner or ref\n    return stop()\nfunc use() -> i32\n    let a: i32 = 1\n    let b: i64 = 2\n    let r: i64 = mk3(b@ref, a@move)\n    return 0\n", "1*NoApplicableOverload_Kd")] // M1s
